    for c in x["commands"]:
        if c["op"] == "push":
            if len(items) == x["capacity"]:
                out.append(False)
            else:
                items.append(c["value"])
                out.append(None)
        elif c["op"] == "pop":
            if items:
                out.append(items.pop(0))
            else:
                out.append(None)
